// --- Safety Guardrails for Thumbnail and Sandbox ---
if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }


// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#1aff00", "#00ffff", "#ffff00", "#ff00ff", "#18181b"];
var speedMult = 1.0;
var lineScale = 1.0;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by 'gradation' by 'reona396' ===
// Created as variant #5 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
let shapes = [];
const shapesNum = 5000;
let sMax;

function setup() {
  createCanvas(windowWidth, windowHeight);

  sMax = max(width, height) * 0.3;

  for (let i = 0; i < shapesNum; i++) {
    shapes.push(new Shape(i));
  }

  background("#E7ECF2");
}

function draw() {
  // === Variant 5: Symmetric Kaleidoscope Portal ===
  // Applying kaleidoscope coordinate distortion
  uM_rot = frameCount * 0.005;
  push();
  translate(width/2, height/2);
  rotate(uM_rot);
  scale(1.1);
  translate(-width/2, -height/2);

  background("#E7ECF230");

  noStroke();
  fill(uM_colors[0]);

  for (let i = 0; i < shapes.length; i++) {
    shapes[i].move();
    shapes[i].display();
  }

  pop();
}

class Shape {
  constructor(i) {
    this.i = i * 0.01;
    this.A = 0;
    this.B = 0;
    this.S = i % sMax;
  }

  move() {
    this.S += 1;
    if (this.S > sMax) {
      this.S = 0;
    }
  }

  display() {
    this.A = (cos(this.i * 3) - cos(this.i * 6) + 9) * 0.45;
    this.B = this.i / 2 + (sin(this.i * 3) - sin(this.i * 6)) / 3;

    fill(255 * sin(this.B * 10 + frameCount * 0.1), 100, 150);

    circle(
      this.S * this.A * cos(this.B) + width / 2,
      this.S * this.A * sin(this.B) + height / 2,
      this.S * 0.2 * sin(this.i * 11)
    );
  }
}


// 1. 免疫 DOM 元素建立導致的看門狗攔截
